return cfg.sources.map(s => ({ json: {
  source: s.id, week: c.toISODate(), cutoff: c.toUTC().toISO(),
  export_url: cfg.library_url + '/' + s.export_path,
  control_url: cfg.library_url + '/' + s.control_path,
